/** State machine system for entity behavior transitions. */

import type { BabylonHandles } from "../adapters/babylonScene.ts";
import type { Resources } from "../kernel/resources.ts";
import type { SignalBus } from "../kernel/signals.ts";
import type { GameSystem } from "../kernel/systems.ts";
import type { EntityId, World } from "../kernel/world.ts";

export type StateMachineComp = {
  initial: string;
  onStompState?: string;
  onHitState?: string;
  onTouchState?: string;
  deathDelay?: number;
  onStateChange?: string;
};

type MachineState = {
  currentState: string;
  previousState: string;
  stateTime: number;
  deathTimer: number | null;
  despawned: boolean;
};

const machineStates = new Map<EntityId, MachineState>();

export function createStateMachineSystem(
  world: World,
  handles: BabylonHandles,
  resources: Resources,
  signals: SignalBus,
): GameSystem {
  return {
    name: "stateMachine",
    order: 22,
    init() {
      for (const [id, raw] of world.query("stateMachine")) {
        const sm = raw as StateMachineComp;
        machineStates.set(id, {
          currentState: sm.initial,
          previousState: sm.initial,
          stateTime: 0,
          deathTimer: null,
          despawned: false,
        });
      }

      // Listen for stomp/hit/touch signals from other systems
      signals.connect("enemy_stomped", (data) => {
        const { enemyId } = data as { enemyId: EntityId; pawnId: EntityId };
        handleStomp(world, handles, signals, enemyId);
      });

      signals.connect("entity_hit", (data) => {
        const { entityId } = data as { entityId: EntityId; damage: number };
        handleHit(world, handles, signals, entityId);
      });

      signals.connect("enemy_touch", (data) => {
        const { enemyId } = data as { enemyId: EntityId; pawnId: EntityId };
        handleTouch(world, handles, signals, enemyId);
      });
    },
    fixedUpdate(ctx) {
      for (const [id, raw] of world.query("stateMachine")) {
        const sm = raw as StateMachineComp;
        const state = machineStates.get(id);
        if (!state || state.despawned) continue;

        state.stateTime += ctx.fixedDt;

        // Handle death delay countdown
        if (state.deathTimer !== null) {
          state.deathTimer -= ctx.fixedDt;
          if (state.deathTimer <= 0) {
            despawnEntity(world, handles, id);
            state.despawned = true;
          }
        }
      }
    },
  };
}

function handleStomp(
  world: World,
  handles: BabylonHandles,
  signals: SignalBus,
  entityId: EntityId,
): void {
  const sm = world.getComponent<StateMachineComp>("stateMachine", entityId);
  if (!sm?.onStompState) return;

  transitionState(world, handles, signals, entityId, sm, sm.onStompState);
}

function handleHit(
  world: World,
  handles: BabylonHandles,
  signals: SignalBus,
  entityId: EntityId,
): void {
  const sm = world.getComponent<StateMachineComp>("stateMachine", entityId);
  if (!sm?.onHitState) return;

  transitionState(world, handles, signals, entityId, sm, sm.onHitState);
}

function handleTouch(
  world: World,
  handles: BabylonHandles,
  signals: SignalBus,
  entityId: EntityId,
): void {
  const sm = world.getComponent<StateMachineComp>("stateMachine", entityId);
  if (!sm?.onTouchState) return;

  transitionState(world, handles, signals, entityId, sm, sm.onTouchState);
}

function transitionState(
  world: World,
  handles: BabylonHandles,
  signals: SignalBus,
  entityId: EntityId,
  sm: StateMachineComp,
  newState: string,
): void {
  const state = machineStates.get(entityId);
  if (!state || state.despawned) return;
  if (state.currentState === newState) return;

  state.previousState = state.currentState;
  state.currentState = newState;
  state.stateTime = 0;

  // Update sprite animation to match state name (convention)
  const sprite = world.getComponent<{ animation?: string }>("sprite", entityId);
  if (sprite) {
    sprite.animation = newState;
    world.addComponent("sprite", entityId, sprite);
  }

  // Check if this is a death state
  const isDeathState = newState === "dead" || newState === "destroyed" || newState === "disabled";
  if (isDeathState && sm.deathDelay != null) {
    state.deathTimer = sm.deathDelay;

    // Disable collider in death state
    const collider = world.getComponent<{ disabled?: boolean }>("collider", entityId);
    if (collider) {
      (collider as Record<string, unknown>).disabled = true;
      world.addComponent("collider", entityId, collider);
    }
  }

  // Emit state change signal
  if (sm.onStateChange) {
    signals.emit(sm.onStateChange, {
      entityId,
      previousState: state.previousState,
      currentState: state.currentState,
    });
  }

  // Always emit generic state_changed signal
  signals.emit("state_changed", {
    entityId,
    previousState: state.previousState,
    currentState: state.currentState,
  });
}

function despawnEntity(world: World, handles: BabylonHandles, entityId: EntityId): void {
  // Hide the entity
  const node = handles.nodes.get(entityId);
  if (node) {
    node.setEnabled(false);
  }

  // Emit despawn signal
  // signals.emit("entity_despawned", { entityId });
}

/** Get the current state of an entity. */
export function getEntityState(entityId: EntityId): string | null {
  return machineStates.get(entityId)?.currentState ?? null;
}

/** Check if an entity is in a specific state. */
export function isInState(entityId: EntityId, stateName: string): boolean {
  return machineStates.get(entityId)?.currentState === stateName;
}

/** Check if an entity has been despawned. */
export function isDespawned(entityId: EntityId): boolean {
  return machineStates.get(entityId)?.despawned ?? false;
}

/** Manually transition an entity to a new state. */
export function setState(
  world: World,
  handles: BabylonHandles,
  signals: SignalBus,
  entityId: EntityId,
  newState: string,
): void {
  const sm = world.getComponent<StateMachineComp>("stateMachine", entityId);
  if (sm) {
    transitionState(world, handles, signals, entityId, sm, newState);
  }
}
